{"command": "DEAL_ID=$(cat /tmp/actlog_seed.json | python3 -c "import sys,json;print(json.load(sys.stdin)['deal_id'])")
curl -s -b /tmp/actlog_cookies.txt "http://127.0.0.1:4031/deals/$DEAL_ID" -o /tmp/deal2.html
echo "rows: $(grep -o 'class=\"activity-row' /tmp/deal2.html | wc -l)"
python3 - <<PY
import re
html = open('/tmp/deal2.html').read()
rows = re.findall(r'<li class="activity-row[^"]*">(.*?)</li>', html, re.S)
def text(row):
    t = re.sub(r'<[^>]+>', ' ', row)
    return re.sub(r'\s+', ' ', t).strip()
for i, r in enumerate(rows, 1):
    print(f"{i}: {text(r)[:120]}")
PY", "description": "Refetch deal page and print log rows in order", "timeout_ms": 30000}

